 let filter=state.filter||'all',sort=state.sort||'smart',subjectFilter=state.subjectFilter||'',priorityFilter=state.priorityFilter||'',deadlineFilter=state.deadlineFilter||'all',searchTerm=state.searchTerm||'',viewMode='list',duration=Number(state.minutes)||25,remaining=duration*60,ticker=null,toastTimer,planRequested=false,selectedPressureDate=dateKey(new Date()),radarView='week',radarMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1,12),selectedFocusTask=state.focusTaskId||'',sessionCompleted=false,focusReturnTarget=null,focusCloseTimer=null,recentCompletionId=null,completionTimer=null,theme='dark';try{theme=localStorage.getItem(THEME_KEY)||'dark'}catch{}document.body.dataset.theme=theme;if(document.documentElement)document.documentElement.style.colorScheme=theme;
