function animateTaskCard(id,kind){if(globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;const list=$('#task-list'),board=$('#task-board');let el=typeof list.querySelector==='function'?list.querySelector('[data-task-id="'+id+'"]'):null;if(!el&&typeof board.querySelector==='function')el=board.querySelector('[data-task-card="'+id+'"]');if(!el||typeof el.animate!=='function')return;const frames=kind==='complete'?[{opacity:.74,transform:'scale(.985)'},{opacity:1,transform:'scale(1)'}]:kind==='settle'?[{transform:'translateY(-5px) scale(.985)'},{transform:'translateY(0) scale(1)'}]:[{opacity:0,transform:'translateY(9px) scale(.985)'},{opacity:1,transform:'translateY(0) scale(1)'}];el.animate(frames,{duration:kind==='settle'?280:380,easing:'cubic-bezier(.2,.75,.25,1)'});if(kind==='complete'){el.classList?.add('is-completing');const check=el.querySelector?.('.task-check, .board-done-label input');if(check?.animate)check.animate([{transform:'scale(.72)'},{transform:'scale(1.22)'},{transform:'scale(1)'}],{duration:360,easing:'cubic-bezier(.2,.75,.25,1)'})}}
 function deadlineSignal(t){const delta=dateOffset(t.due),today=dateKey(new Date()),todaysOpen=state.tasks.filter(x=>x.due===today&&!x.done),available=Number($('#available-minutes').value),todayLoad=todaysOpen.reduce((n,x)=>n+(Number(x.duration)||0),0),overCapacity=Number.isFinite(available)&&available>=15&&todayLoad>available;if(delta<0)return {label:'Overdue',kind:'overdue'};if(delta===0&&overCapacity)return {label:'At risk today',kind:'risk'};if(delta>=0&&delta<=2)return {label:delta===0?'Due today':'Due soon',kind:'soon'};return null}
 function renderDeadlineWarnings(){const box=$('#deadline-warnings'),today=dateKey(new Date()),todayTasks=state.tasks.filter(t=>t.due===today&&!t.done),available=Number($('#available-minutes').value),todayLoad=todayTasks.reduce((n,t)=>n+(Number(t.duration)||0),0),overCapacity=Number.isFinite(available)&&available>=15&&todayLoad>available,warnings=state.tasks.filter(t=>!t.done).map(t=>({task:t,signal:deadlineSignal(t)})).filter(x=>x.signal);if(!warnings.length){box.innerHTML='<div class="deadline-clear"><span class="clear-mark">✓</span><span><strong>No urgent deadlines.</strong> Keep your next step small and steady.</span></div>';return}const shown=warnings.slice(0,4);box.innerHTML='<div class="deadline-warning-head"><div><span class="eyebrow"><span class="eyebrow-line"></span>DEADLINE CHECK-IN</span><strong>'+warnings.length+' assignment'+(warnings.length===1?' needs':'s need')+' a look</strong></div><button type="button" class="warning-action" data-review-rescue>Review in Rescue My Day ↗</button></div>'+(overCapacity?'<p class="deadline-capacity-note">Today’s tasks total '+todayLoad+' estimated minutes, above the '+available+' minutes available in your Rescue My Day window.</p>':'')+'<p class="deadline-warning-explainer">Due soon means within 48 hours. At risk means today’s task estimates exceed the available study window. Overdue means the due date has passed.</p><div class="deadline-warning-list">'+shown.map(x=>'<div class="deadline-warning-item"><span class="signal-pill '+x.signal.kind+'">'+x.signal.label+'</span><strong>'+esc(x.task.title)+'</strong><span>'+esc(x.task.subject)+' · '+x.task.duration+' min · '+fmtDue(x.task.due)[0]+'</span></div>').join('')+(warnings.length>shown.length?'<span class="warning-more">+'+(warnings.length-shown.length)+' more in your planner</span>':'')+'</div>'}
